mapper.select:
SELECT  FROM wardrobe_item i
WHERE i.user_id=#{userId}
AND i.name LIKE CONCAT('%',#{keyword},'%')
AND i.category=#{category}
AND i.color=#{color}
AND JSON_CONTAINS(i.seasons_json,JSON_QUOTE(#{season}))
AND JSON_CONTAINS(i.occasions_json,JSON_QUOTE(#{occasion}))
ORDER BY i.id DESC

mapper.update:
UPDATE wardrobe_item SET name=#{name},category=#{category},color=#{color},seasons_json=#{seasonsJson},
occasions_json=#{occasionsJson},note=#{note}
WHERE user_id=#{userId} AND id=#{id}
